#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    char name[51];
    int roll_number;
    float marks1, marks2, marks3;
    float total;
    float average;
} Student;

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n < 1 || n > 100) return 0;

    Student students[100];

    for (int i = 0; i < n; i++) {
        scanf("%50s %d %f %f %f", students[i].name, &students[i].roll_number,
              &students[i].marks1, &students[i].marks2, &students[i].marks3);
        students[i].total = students[i].marks1 + students[i].marks2 + students[i].marks3;
        students[i].average = students[i].total / 3.0f;
    }

    // Bubble sort by average descending
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (students[j].average < students[j + 1].average) {
                Student temp = students[j];
                students[j] = students[j + 1];
                students[j + 1] = temp;
            }
        }
    }

    printf("Student Information Sorted by Average Marks:\n");
    for (int i = 0; i < n; i++) {
        printf("Name: %s, Roll Number: %d, Total Marks: %.2f, Average Marks: %.2f\n",
               students[i].name, students[i].roll_number, students[i].total, students[i].average);
    }

    return 0;
}
